/* ChessPulse design tokens.
   Single source for colour roles, type scale, spacing, radii, borders, motion.
   styles.css and components read these variables only; no raw values. */
:root {
  /* Colour roles (dark, single theme). Accent is reserved for the elevated state only. */
  --bg: #0e1012;
  --surface: #161a1d;
  --line: #262c31;
  --text: #e9e7e3;
  --muted: #98a0a6;
  --accent: #e0663a;
  --ok: #6f8f7b;
  --warn: #c9a227;
  --danger: #c94a3a;
  --focus: #e9e7e3;

  /* Type scale (px). */
  --fs-xs: 12px;
  --fs-sm: 14px;
  --fs-base: 16px;
  --fs-md: 20px;
  --fs-lg: 28px;
  --fs-xl: 40px;

  /* Spacing grid (4 px). */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 24px;
  --sp-6: 32px;
  --sp-7: 48px;

  /* Radii. */
  --r-control: 4px;
  --r-panel: 8px;

  /* Border. */
  --border-w: 1px;

  /* Motion. */
  --motion-fast: 120ms;
  --motion-medium: 200ms;

  /* Font families. */
  --font-ui: "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SFMono-Regular", monospace;
}

/* Reduced motion: collapse durations. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --motion-fast: 0ms;
    --motion-medium: 0ms;
  }
}

